  if (texel.b > 0.998) {
    return b3dUnpackOne(texel.r, 0.0, face, cell, viewDir)
      + b3dUnpackOne(texel.g, 1.0, face, cell, viewDir)
      + b3dUnpackOne(texel.a, 2.0, face, cell, viewDir);
  }

